#!/usr/bin/env bash
# Wall-clock comparison across implementations of LeetCode #895.
# See ../README.md § Benchmarks for what these numbers mean.
#
# Generated by scripts/new-bench.sh — keep in sync via that script.
# Seq-only kata. Requires: hyperfine, rustc, clang, go, karac.

set -euo pipefail
cd "$(dirname "$0")"

STEM=freq_stack

require() {
    if ! command -v "$1" >/dev/null 2>&1; then
        echo "$1 not found — install with: $2" >&2
        exit 1
    fi
}

require hyperfine "brew install hyperfine"
require rustc     "rustup (https://rustup.rs) or 'brew install rustup-init'"
require clang     "xcode-select --install (macOS) or your distro's clang package"
require go        "brew install go  or your distro's golang package"
require karac     "cargo install --path . --features llvm  (from karac-rust checkout)"

if [ "${BENCH_JSON:-1}" = "1" ]; then
    require jq      "brew install jq"
    require python3 "python3 ships with macOS; or 'brew install python'"
fi
ROOT="$(cd ../../../.. && pwd)"
. "$ROOT/scripts/bench-lib.sh"

mkdir -p target

# Equal-safety Rust twin: rustc with overflow checks ON, matching kāra's
# default-checked arithmetic.
build_rust_ovf() {
    local src="$1"
    local out="target/$(basename "$src" .rs)_ovf"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ]; then
        echo "compiling $src (overflow-checks=on, equal-safety) ..." >&2
        rustc -O -C overflow-checks=on "$src" -o "$out"
    fi
}

build_rust() {
    local src="$1"
    local out="target/$(basename "$src" .rs)"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ]; then
        echo "compiling $src ..." >&2
        rustc -O "$src" -o "$out"
    fi
}

build_c() {
    local src="$1"
    local out="target/$(basename "$src" .c)_c"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ]; then
        echo "compiling $src ..." >&2
        clang -O3 "$src" -o "$out"
    fi
}

build_kara_par() {
    local src="$1"
    local stem="$(basename "$src" .kara)"
    local out="target/${stem}_kara_par"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ] || [ "$(command -v karac)" -nt "$out" ]; then
        echo "compiling $src (auto-par default) ..." >&2
        karac build "$src" >/dev/null
        mv "$stem" "$out"
    fi
}

build_rayon() {
    local out="target/${STEM}_rayon"
    local src="rayon/src/main.rs"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ]; then
        echo "building rayon variant (cargo) ..." >&2
        ( cd rayon && cargo build --release --quiet )
        cp -f "rayon/target/release/${STEM}_rayon" "$out"
    fi
}

build_go_par() {
    local out="target/${STEM}_go_par"
    local src="go-par/main.go"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ]; then
        echo "compiling go-par ..." >&2
        ( cd go-par && go build -o "../$out" . )
    fi
}

build_kara() {
    local src="$1"
    local stem="$(basename "$src" .kara)"
    local out="target/${stem}_kara"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ] || [ "$(command -v karac)" -nt "$out" ]; then
        echo "compiling $src (seq, KARAC_AUTO_PAR=0) ..." >&2
        KARAC_AUTO_PAR=0 karac build "$src" >/dev/null
        mv "$stem" "$out"
    fi
}

build_go_seq() {
    local out="target/${STEM}_go_seq"
    local src="go-seq/main.go"
    if [ ! -x "$out" ] || [ "$src" -nt "$out" ] || [ "$(command -v karac)" -nt "$out" ]; then
        echo "compiling go-seq ..." >&2
        ( cd go-seq && go build -o "../$out" . )
    fi
}

build_rust "${STEM}.rs"
build_rust_ovf "${STEM}.rs"
build_c    "${STEM}.c"
build_kara "${STEM}.kara"
build_go_seq
build_kara_par "${STEM}.kara"
build_rayon
build_go_par
# Matched-ISA twins (equal safety + equal ISA). No-ops off x86-64.
isa_build_c    "${STEM}.c"
isa_build_rust "${STEM}.rs"

expected=$(./target/${STEM}_kara)
mismatch=""
for pair in \
    "rust:./target/${STEM}" \
    "rust_ovf:./target/${STEM}_ovf" \
    "c:./target/${STEM}_c" \
    "go:./target/${STEM}_go_seq" \
    "kara_par:./target/${STEM}_kara_par" \
    "rayon:./target/${STEM}_rayon" \
    "go_par:./target/${STEM}_go_par" \
    $(isa_sinks "${STEM}"); do
    name="${pair%%:*}"
    cmd="${pair#*:}"
    out=$("$cmd")
    if [ "$out" != "$expected" ]; then
        mismatch="$mismatch ${name}=${out}"
    fi
done
if [ -n "$mismatch" ]; then
    echo "sink mismatch (expected=$expected):$mismatch" >&2
    exit 1
fi
echo "sink (kara/rust/c/go): $expected"
if [ "${KARA_BENCH_INCLUDE_PY:-0}" = "1" ]; then
    py_out=$(python3 "${STEM}.py")
    if [ "$py_out" != "$expected" ]; then
        echo "python sink mismatch: py=$py_out" >&2
        exit 1
    fi
    echo "python: matches"
fi
echo

bench_begin id=895 slug=maximum-frequency-stack group=801-900 \
    title="Maximum Frequency Stack" \
    workload="120 rounds x 3,000 LCG-driven push/pop steps over a 12-value domain; Map[i64, Vec[i64]] bucket read-modify-written on every op; sink=3299190" sink="$expected"

echo "=== runtime — short workloads (compiled) ==="
rt_begin --warmup 5 --runs 30
rt_cmd --lang kara --approach "$STEM" --lane seq --mode codegen \
    --name "kara ${STEM} (codegen)" --cmd "./target/${STEM}_kara"
rt_cmd --lang rust --approach "$STEM" --lane seq --mode native \
    --name "rust ${STEM}" --cmd "./target/${STEM}"
rt_cmd --lang rust_ovf --approach "$STEM" --lane seq --mode native \
    --name "rust ${STEM} (overflow-checks=on, equal-safety)" --cmd "./target/${STEM}_ovf"
rt_cmd --lang c --approach "$STEM" --lane seq --mode native \
    --name "c    ${STEM}" --cmd "./target/${STEM}_c"
rt_cmd --lang go --approach "$STEM" --lane seq --mode native \
    --name "go   ${STEM}" --cmd "./target/${STEM}_go_seq"
isa_rt_cmds "$STEM" seq
rt_end

echo
echo "=== runtime — PAR LANE (multi-core: auto-par vs hand-tuned) ==="
# All three parallelize the SAME reduction over independent rounds. Kara's
# default `karac build` got there with NO parallel source — auto-par-on-
# reduction recognized `checksum = checksum + round(r, steps)` and emitted a
# karac_par_reduce dispatch — while Rust needed rayon's `into_par_iter` and Go
# needed hand-written goroutine chunking + WaitGroup + partial merge.
#
# Apples-to-apples WITHIN this lane only. Per BENCH.md's two-lane discipline
# these are NOT comparable to the single-threaded rows above.
#
# Worth stating plainly: the loop body here ALLOCATES — a fresh FreqStack with
# two maps per round — so this exercises auto-par over heap-churning work
# rather than the arithmetic kernels that lane usually shows.
rt_begin --warmup 5 --runs 30
rt_cmd --lang kara --approach "${STEM}" --lane par --mode codegen \
    --name "kara  ${STEM} (auto-par, NO parallel code)" --cmd "./target/${STEM}_kara_par"
rt_cmd --lang rust --approach "${STEM}" --lane par --mode native \
    --name "rust  ${STEM} (rayon par_iter)" --cmd "./target/${STEM}_rayon"
rt_cmd --lang go --approach "${STEM}" --lane par --mode native \
    --name "go    ${STEM} (goroutines + WaitGroup)" --cmd "./target/${STEM}_go_par"
rt_end

echo
echo "=== runtime — long workloads (py) ==="
rt_begin --warmup 1 --runs 3
rt_cmd --lang python --approach "$STEM" --lane seq --mode interp \
    --name "py   ${STEM}" --cmd "python3 ${STEM}.py"
rt_end

echo
echo "=== compile elapsed (cold) ==="
ce_begin --warmup 1 --runs 10
ce_cmd --lang kara --approach "$STEM" --mode codegen \
    --prepare "rm -f target/${STEM}_kara.ce ${STEM}" \
    --name "karac build ${STEM}.kara" \
    --cmd "sh -c \"karac build ${STEM}.kara >/dev/null && mv ${STEM} target/${STEM}_kara.ce\""
ce_cmd --lang rust --approach "$STEM" --mode native \
    --prepare "rm -f target/${STEM}" \
    --name "rustc -O ${STEM}.rs" --cmd "rustc -O ${STEM}.rs -o target/${STEM}"
ce_cmd --lang c --approach "$STEM" --mode native \
    --prepare "rm -f target/${STEM}_c" \
    --name "clang -O3 ${STEM}.c" --cmd "clang -O3 ${STEM}.c -o target/${STEM}_c"
ce_end

echo
echo "=== binary size ==="
size_put --lang kara --approach "$STEM" --lane seq --mode codegen --path "target/${STEM}_kara"
size_put --lang rust --approach "$STEM" --lane seq --mode native  --path "target/${STEM}"
size_put --lang c    --approach "$STEM" --lane seq --mode native  --path "target/${STEM}_c"
size_put --lang go   --approach "$STEM" --lane seq --mode native  --path "target/${STEM}_go_seq"

echo
echo "=== runtime memory (peak) ==="
mem_put --lang kara --approach "$STEM" --lane seq --mode codegen --bytes "$(mem_peak ./target/${STEM}_kara)"
mem_put --lang rust --approach "$STEM" --lane seq --mode native  --bytes "$(mem_peak ./target/${STEM})"
mem_put --lang c    --approach "$STEM" --lane seq --mode native  --bytes "$(mem_peak ./target/${STEM}_c)"
mem_put --lang go   --approach "$STEM" --lane seq --mode native  --bytes "$(mem_peak ./target/${STEM}_go_seq)"
mem_put --lang python --approach "$STEM" --lane seq --mode interp --bytes "$(mem_peak python3 ${STEM}.py)"

echo
echo "=== compile memory (cold) ==="
# NOTE: measure the cold compile WITHOUT touching the benchmarked binary.
# That path holds the KARAC_AUTO_PAR=0 build the seq runtime lane measures;
# a plain `karac build` here is an AUTO-PAR build, so moving it into place
# left the next run's build_kara freshness check satisfied and the seq lane
# silently measuring an auto-par binary.
rm -f "${STEM}"
bytes=$(mem_peak karac build "${STEM}.kara")
rm -f "${STEM}"
cmem_put --lang kara --approach "${STEM}" --mode codegen --bytes "$bytes"
rm -f "target/${STEM}"
cmem_put --lang rust --approach "${STEM}" --mode native --bytes "$(mem_peak rustc -O "${STEM}.rs" -o "target/${STEM}")"
rm -f "target/${STEM}_c"
cmem_put --lang c --approach "${STEM}" --mode native --bytes "$(mem_peak clang -O3 "${STEM}.c" -o "target/${STEM}_c")"

echo
bench_emit
